struct CorrelatedEquilibrium end

function solve(M::CorrelatedEquilibrium, P::SimpleGame)

    I, A, R = P.I, P.A, P.R

    model = Model(Ipopt.Optimizer)

    @variable(model, π[joint(A)] ≥ 0)

    @objective(model, Max, sum(sum(π[a]*R(a) for a in joint(A))))

    @constraint(model, [i=I, ai=A[i], ai'=A[i]],

        sum(R(a)[i]*π[a] for a in joint(A) if a[i]==ai)

        ≥ sum(R(joint(a,ai',i))[i]*π[a] for a in joint(A) if a[i]==ai))

    @constraint(model, sum(π) == 1)

    optimize!(model)

    return JointCorrelatedPolicy(a ⇒ value(π[a]) for a in joint(A))

end

